// Extrai e sanitiza os dados do proponente
const body = $json.body || $json;
const rawPhone = String(body.telefone || body.phone || '').replace(/\D/g, '');
const phone = rawPhone.startsWith('55') ? rawPhone : (rawPhone.length >= 10 ? '55' + rawPhone : '');
const nome = body.nome || body.name || 'Proponente';
const duvida = body.duvida || body.mensagem || 'Gostaria de saber como aprovar meu projeto no edital';
const editalNome = body.edital_nome || 'Edital Cultural / Licitação';

return [{
  json: {
    phone,
    nome,
    duvida,
    editalNome,
    timestamp: new Date().toISOString()
  }
}];

const llmRaw = $json.candidates?.[0]?.content?.parts?.[0]?.text || 'Olá! Recebemos sua dúvida sobre o edital. Nossa plataforma EditalAudit AI está pronta para auditar sua proposta com os 14 pareceristas M.U.S.A. Acesse com seu primeiro crédito gratuito!';
const lead = $('Sanitizar Dados do Proponente').first().json;

const msgWhatsApp = `⚖️ *EditalAudit AI — Consultoria Especializada*

Olá, *${lead.nome}*!

${llmRaw.trim()}

🔗 *Acesse sua bancada de auditoria:* https://editalaudit.ai
💳 *Seu 1º crédito gratuito já está disponível!*`;

return [{
  json: {
    number: lead.phone,
    text: msgWhatsApp
  }
}];
